<?php
require_once __DIR__.'/../../includes/session.php';
$title = 'Manutenções - '.APP_NAME;use Controllers\AuthController;use Models\Maintenance;use Models\Equipment;use Models\User;AuthController::requireRole('admin','coordinator','technician');$canManage=can('manage_maintenance');$items=Maintenance::all();$equipment=$canManage?array_values(array_filter(Equipment::all(),fn($e)=>!in_array($e['status'],['borrowed','inactive'],true))):[];$staff=$canManage?User::activeStaff():[];$api=appUrl('/api/maintenance.php');require_once __DIR__.'/../partials/header.php';
?>
<div class="page-header"><div><h1 class="page-title">Manutenções</h1><p class="page-subtitle">Registre problemas, reparos e manutenções preventivas do patrimônio escolar.</p></div><?php if($canManage):?><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#maintenanceModal" onclick="newMaintenance()"><i data-lucide="plus"></i> Nova manutenção</button><?php endif;?></div>
<div class="card"><div class="card-header"><div class="search-box"><i data-lucide="search"></i><input class="form-control" placeholder="Buscar equipamento ou responsável" data-search-table="#maintenanceTable"></div></div><div class="card-body p-0 p-md-3"><div class="table-responsive"><table class="table mobile-cards" id="maintenanceTable"><thead><tr><th>Equipamento</th><th>Tipo</th><th>Responsável</th><th>Início</th><th>Conclusão</th><th>Status</th><th>Custo</th><?php if($canManage):?><th class="text-end">Ações</th><?php endif;?></tr></thead><tbody><?php foreach($items as $m):?><tr><td data-label="Equipamento"><strong><?=e($m['equipment_name'])?></strong><small class="d-block muted"><?=e($m['patrimony_code'])?></small></td><td data-label="Tipo"><?=getStatusBadge($m['type'])?></td><td data-label="Responsável"><?=e($m['technician_name'])?></td><td data-label="Início"><?=e(formatDate($m['maintenance_date']))?></td><td data-label="Conclusão"><?=e(formatDate($m['completion_date']))?></td><td data-label="Status"><?=getStatusBadge($m['status'])?></td><td data-label="Custo"><?=e(formatCurrency($m['cost']))?></td><?php if($canManage):?><td data-label="Ações"><div class="table-actions"><button class="btn btn-outline-primary btn-sm" onclick="editMaintenance(<?=$m['id']?>)"><i data-lucide="pencil"></i> Editar</button></div></td><?php endif;?></tr><?php endforeach;?></tbody></table></div><?php if(!$items):?><div class="empty-state"><i data-lucide="wrench"></i><div>Nenhuma manutenção registrada.</div></div><?php endif;?></div></div>
<?php if($canManage):?><div class="modal fade" id="maintenanceModal" tabindex="-1"><div class="modal-dialog modal-lg modal-dialog-scrollable"><div class="modal-content"><form id="maintenanceForm"><div class="modal-header"><h2 class="modal-title fs-5" id="maintenanceTitle">Nova manutenção</h2><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><?=csrfField()?><input type="hidden" name="action" id="maintenanceAction" value="create"><input type="hidden" name="id" id="maintenanceId"><div class="row g-3"><div class="col-md-6"><label class="form-label">Equipamento *</label><select class="form-select" name="equipment_id" id="mEquipment" required><option value="">Selecione...</option><?php foreach($equipment as $e):?><option value="<?=$e['id']?>"><?=e($e['name'].' • '.$e['patrimony_code'])?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Responsável técnico *</label><select class="form-select" name="technician_id" id="mTech" required><?php foreach($staff as $u):?><option value="<?=$u['id']?>" <?=$u['id']==($_SESSION['user_id']??0)?'selected':''?>><?=e($u['name'])?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">Tipo *</label><select class="form-select" name="type" id="mType"><option value="corrective">Corretiva</option><option value="preventive">Preventiva</option></select></div><div class="col-md-4"><label class="form-label">Data de início *</label><input class="form-control" type="date" name="maintenance_date" id="mDate" required></div><div class="col-md-4"><label class="form-label">Status *</label><select class="form-select" name="status" id="mStatus"><option value="pending">Pendente</option><option value="in_progress">Em andamento</option><option value="completed">Concluído</option></select></div><div class="col-md-4"><label class="form-label">Conclusão</label><input class="form-control" type="date" name="completion_date" id="mCompletion"></div><div class="col-md-4"><label class="form-label">Custo</label><input class="form-control" type="number" min="0" step="0.01" name="cost" id="mCost"></div><div class="col-12"><label class="form-label">Descrição do problema/serviço *</label><textarea class="form-control" rows="3" name="description" id="mDescription" required></textarea></div><div class="col-12"><label class="form-label">Observações</label><textarea class="form-control" rows="2" name="observations" id="mNotes"></textarea></div></div></div><div class="modal-footer"><button type="button" class="btn btn-outline-secondary" data-bs-dismiss="modal">Cancelar</button><button class="btn btn-primary">Salvar</button></div></form></div></div></div>
<script>
const maintenanceApi=<?=json_encode($api)?>;function newMaintenance(){maintenanceForm.reset();maintenanceAction.value='create';maintenanceId.value='';maintenanceTitle.textContent='Nova manutenção';mDate.value=new Date().toISOString().slice(0,10);mTech.value=<?=json_encode((string)($_SESSION['user_id']??''))?>;mType.value='corrective';mStatus.value='pending';mEquipment.disabled=false}async function editMaintenance(id){try{const r=await fetch(maintenanceApi+'?action=show&id='+id),d=await r.json();if(!d.success)throw new Error(d.message);const x=d.data;maintenanceAction.value='update';maintenanceId.value=x.id;mEquipment.value=x.equipment_id;mEquipment.disabled=true;mTech.value=x.technician_id;mType.value=x.type;mDate.value=x.maintenance_date;mStatus.value=x.status;mCompletion.value=x.completion_date||'';mCost.value=x.cost||'';mDescription.value=x.description||'';mNotes.value=x.observations||'';maintenanceTitle.textContent='Editar manutenção';new bootstrap.Modal(document.getElementById('maintenanceModal')).show()}catch(e){notifyError(e)}}maintenanceForm.addEventListener('submit',async e=>{e.preventDefault();mEquipment.disabled=false;try{await apiPost(maintenanceApi,new FormData(e.target));location.reload()}catch(err){notifyError(err)}})
</script><?php endif;?>
<?php require_once __DIR__.'/../partials/footer.php';?>
